def kl_error(self, input_data, targets, average=True,
                 cache=None, prediction=True):
        """ The KL divergence error
        """
        if cache is None:
            # Predict
            y_pred = self.predict(input_data)

            # Calculate KL divergence
            kl_divergence = (
                y_pred * (
                    torch.log(y_pred) - torch.log(targets)
                ).exp()
            ).sum()

            # Average
            if average:
                kl_divergence = kl_divergence.mean()

        else:
            # Predict
            y_pred = cache

            # Calculate KL divergence
            kl_divergence = (
                y_pred * (
                    torch.log(y_pred) - torch.log(targets)
                ).exp()
            ).sum()

            # Average
            if average:
                kl_divergence = kl_divergence.mean()

        if prediction:
            return y_pred, kl_divergence

        return kl_divergence

